using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class BeachCartRoadFacing{static BeachCartRoadFacing(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachCartRoadFacing.request"))return;File.Delete("BeachCartRoadFacing.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="15 Beach Food Carts");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCartRoadFacing");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCartRoadFacing/Scene.unity",true);foreach(Transform cart in root.transform)cart.rotation=cart.rotation*Quaternion.Euler(0,180,0);PrefabUtility.SaveAsPrefabAssetAndConnect(root,"Assets/Scenes/Oasis/SouthBeach/FoodCarts/15 Beach Food Carts.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/BeachCartRoadFacing.txt","SUCCESS rotated "+root.transform.childCount+" cart fronts 180 degrees from sea toward road; positions and colors unchanged. Scene and master prefab saved.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachCartRoadFacing.txt",e.ToString());Debug.LogException(e);}}}
